+REVOKE PERSIST_RO_VARIABLES_ADMIN, GRANT OPTION ON *.* FROM u1;
+FLUSH PRIVILEGES;
+SHOW GRANTS FOR u1;
+# all dynamic privilege should have "WITH_GRANT_OPTION" set to NO
